        entity.HasDiscriminator<string>("Discriminator");

        // EF9: id values no longer include the discriminator prefix.
        // Existing documents have ids like "Product|123"; keep that format.
        entity.HasRootDiscriminatorInJsonId(true);
    });
    // EF9: HasIndex now throws for Cosmos entities. Removed.
    // Manage indexing via the container's indexing policy in Azure Portal/Bicep/Terraform.
}

